

'use strict';
let ACTIVE_REQUEST_ID=null;
function emit(message,transfer){
  if(ACTIVE_REQUEST_ID&&message&&message.requestId==null)message.requestId=ACTIVE_REQUEST_ID;
  self.postMessage(message,transfer||[]);
}
/* ========================================================================
   Detection engine.  Runs in a worker; caches intermediates so that
   changing a shape limit is instant and only signal-level changes
   trigger a full recomputation.
   ====================================================================== */

function boxBlur1(src,dst,w,h,r){
  const span=2*r+1, inv=1/span, tmp=new Float32Array(w*h);
  for(let y=0;y<h;y++){const o=y*w;let s=0;
    for(let x=-r;x<=r;x++) s+=src[o+Math.min(w-1,Math.max(0,x))];
    for(let x=0;x<w;x++){tmp[o+x]=s*inv;
      s+=src[o+Math.min(w-1,x+r+1)]-src[o+Math.max(0,x-r)];}}
  for(let x=0;x<w;x++){let s=0;
    for(let y=-r;y<=r;y++) s+=tmp[Math.min(h-1,Math.max(0,y))*w+x];
    for(let y=0;y<h;y++){dst[y*w+x]=s*inv;
      s+=tmp[Math.min(h-1,y+r+1)*w+x]-tmp[Math.max(0,y-r)*w+x];}}
}
function gaussian(src,w,h,sigma){
  const r=Math.max(1,Math.round(sigma*0.9));
  const a=new Float32Array(src.length), b=new Float32Array(src.length);
  boxBlur1(src,a,w,h,r); boxBlur1(a,b,w,h,r); boxBlur1(b,a,w,h,r); return a;
}
/* exact Euclidean distance transform, Felzenszwalb & Huttenlocher */
function edt(bin,w,h,inside){
  const INF=1e20, n=Math.max(w,h);
  const f=new Float64Array(n), d=new Float64Array(n), v=new Int32Array(n), z=new Float64Array(n+1);
  const g=new Float64Array(w*h);
  for(let i=0;i<w*h;i++) g[i]=(bin[i]===inside)?INF:0;
  function pass(len,rd,wr){
    for(let i=0;i<len;i++) f[i]=rd(i);
    let k=0; v[0]=0; z[0]=-INF; z[1]=INF;
    for(let q=1;q<len;q++){
      let s;
      for(;;){const p=v[k]; s=((f[q]+q*q)-(f[p]+p*p))/(2*q-2*p);
        if(s<=z[k]) k--; else break;}
      k++; v[k]=q; z[k]=s; z[k+1]=INF;
    }
    k=0;
    for(let q=0;q<len;q++){while(z[k+1]<q)k++;const p=v[k];d[q]=(q-p)*(q-p)+f[p];}
    for(let i=0;i<len;i++) wr(i,d[i]);
  }
  for(let x=0;x<w;x++) pass(h,i=>g[i*w+x],(i,val)=>{g[i*w+x]=val;});
  for(let y=0;y<h;y++){const o=y*w; pass(w,i=>g[o+i],(i,val)=>{g[o+i]=val;});}
  const out=new Float32Array(w*h);
  for(let i=0;i<w*h;i++) out[i]=Math.sqrt(g[i]);
  return out;
}
function upsample(src,sw,sh,w,h){
  const out=new Float32Array(w*h), fx=sw/w, fy=sh/h;
  for(let y=0;y<h;y++){
    const gy=Math.min(sh-1.001,y*fy), y0=gy|0, ty=gy-y0, y1=Math.min(sh-1,y0+1);
    for(let x=0;x<w;x++){
      const gx=Math.min(sw-1.001,x*fx), x0=gx|0, tx=gx-x0, x1=Math.min(sw-1,x0+1);
      const a=src[y0*sw+x0],b=src[y0*sw+x1],c=src[y1*sw+x0],dd=src[y1*sw+x1];
      const t=a+(b-a)*tx;
      out[y*w+x]=t+((c+(dd-c)*tx)-t)*ty;
    }
  }
  return out;
}
/* Tissue versus empty slide.  Empty slide is not black: it still carries
   camera offset and stray light, and it is *uniform*, so a background window
   that straddles the boundary collapses both the local background and the
   local noise scale.  Faint texture just inside the tissue then reads as many
   sigma and generates a cluster of phantom somata along the edge.  Everything
   below exists to stop that.                                              */
function tissueMask(img,w,h){
  const f=8, dw=Math.max(4,Math.ceil(w/f)), dh=Math.max(4,Math.ceil(h/f));
  const ds=new Float32Array(dw*dh);
  for(let y=0;y<dh;y++){
    const y0=Math.min(h-1,y*f), y1=Math.min(h,y0+f);
    for(let x=0;x<dw;x++){
      const x0=Math.min(w-1,x*f), x1=Math.min(w,x0+f);
      let sum=0,n=0;
      for(let yy=y0;yy<y1;yy+=2)for(let xx=x0;xx<x1;xx+=2){sum+=img[yy*w+xx];n++;}
      ds[y*dw+x]=n?sum/n:0;
    }
  }
  const sm=gaussian(ds,dw,dh,2.0);
  const srt=Float32Array.from(sm); Array.prototype.sort.call(srt,(a,b)=>a-b);
  const q=f2=>srt[Math.floor(f2*(srt.length-1))];
  const lo=q(0.02), mid=q(0.60);
  /* Is there empty slide in frame at all?  Empty slide forms a tight plateau at
     the bottom of the range; tissue that fills the frame does not.  Without this
     check a smooth dim periphery gets mistaken for slide and real somata there
     are thrown away.                                                          */
  let plateau=0; const cut=lo+0.05*(mid-lo);
  for(let i=0;i<sm.length;i++) if(sm[i]<cut) plateau++;
  const hasSlide=(plateau/sm.length)>0.10;
  const m=new Uint8Array(dw*dh);
  if(!hasSlide){ m.fill(1); return {m,dw,dh,f,hasSlide:false}; }
  const slide=q(0.05), thr=slide+0.12*(mid-slide);
  for(let i=0;i<m.length;i++) m[i]=sm[i]>thr?1:0;
  /* keep the largest piece, then fill interior holes */
  {
    const cc=labelComponents(m,dw,dh), cnt=new Int32Array(cc.count+1);
    for(let i=0;i<cc.lab.length;i++) if(cc.lab[i]) cnt[cc.lab[i]]++;
    let best=0,bi=0;
    for(let L=1;L<=cc.count;L++) if(cnt[L]>best){best=cnt[L];bi=L;}
    for(let i=0;i<m.length;i++) m[i]=(cc.lab[i]===bi)?1:0;
  }
  {
    const inv=new Uint8Array(dw*dh);
    for(let i=0;i<inv.length;i++) inv[i]=m[i]?0:1;
    const cc=labelComponents(inv,dw,dh);
    const outside=new Uint8Array(cc.count+1);
    for(let x=0;x<dw;x++){if(cc.lab[x])outside[cc.lab[x]]=1;
      if(cc.lab[(dh-1)*dw+x])outside[cc.lab[(dh-1)*dw+x]]=1;}
    for(let y=0;y<dh;y++){if(cc.lab[y*dw])outside[cc.lab[y*dw]]=1;
      if(cc.lab[y*dw+dw-1])outside[cc.lab[y*dw+dw-1]]=1;}
    for(let i=0;i<m.length;i++) if(!m[i]&&cc.lab[i]&&!outside[cc.lab[i]]) m[i]=1;
  }
  return {m,dw,dh,f,hasSlide:true};
}
/* tissue eroded by `margin` px: the region where the background model is
   trustworthy and detection is allowed */
function validRegion(t,w,h,margin){
  const d=edt(t.m,t.dw,t.dh,1);
  const r=margin/t.f;
  const sm=new Float32Array(t.dw*t.dh);
  for(let i=0;i<sm.length;i++) sm[i]=d[i]>r?1:0;
  const up=upsample(sm,t.dw,t.dh,w,h);
  const out=new Uint8Array(w*h);
  for(let i=0;i<out.length;i++) out[i]=up[i]>0.5?1:0;
  return out;
}
function localBackground(img,w,h,radius,tis){
  const f=Math.max(1,Math.round(radius/8));
  const dw=Math.max(2,Math.ceil(w/f)), dh=Math.max(2,Math.ceil(h/f));
  const ds=new Float32Array(dw*dh);
  for(let y=0;y<dh;y++){const sy=Math.min(h-1,y*f);
    for(let x=0;x<dw;x++) ds[y*dw+x]=img[sy*w+Math.min(w-1,x*f)];}
  /* tissue flag at the downsampled grid, so slide pixels can be excluded
     from the percentile that defines local background */
  let tflag=null;
  if(tis){
    tflag=new Uint8Array(dw*dh);
    for(let y=0;y<dh;y++)for(let x=0;x<dw;x++){
      const ty=Math.min(tis.dh-1,Math.floor(y*f/tis.f));
      const tx=Math.min(tis.dw-1,Math.floor(x*f/tis.f));
      tflag[y*dw+x]=tis.m[ty*tis.dw+tx];
    }
  }
  const r=Math.max(2,Math.round(radius/f));
  const bg=new Float32Array(dw*dh), buf=new Float32Array((2*r+1)*(2*r+1));
  for(let y=0;y<dh;y++)for(let x=0;x<dw;x++){
    let n=0;
    const y0=Math.max(0,y-r),y1=Math.min(dh-1,y+r),x0=Math.max(0,x-r),x1=Math.min(dw-1,x+r);
    for(let yy=y0;yy<=y1;yy+=2)for(let xx=x0;xx<=x1;xx+=2){
      const j=yy*dw+xx;
      if(tflag&&!tflag[j])continue;          // ignore empty slide
      buf[n++]=ds[j];
    }
    if(n<8){                                  // window is mostly slide: widen it
      n=0;
      for(let yy=y0;yy<=y1;yy+=2)for(let xx=x0;xx<=x1;xx+=2) buf[n++]=ds[yy*dw+xx];
    }
    const s=buf.subarray(0,n); Array.prototype.sort.call(s,(a,b)=>a-b);
    bg[y*dw+x]=s[Math.floor(0.10*(n-1))];
  }
  return upsample(bg,dw,dh,w,h);
}
function localSigma(resid,w,h,tile,tisFull){
  const nx=Math.max(1,Math.floor(w/tile)), ny=Math.max(1,Math.floor(h/tile));
  const map=new Float32Array(nx*ny);
  const vals=[];
  for(let ty=0;ty<ny;ty++)for(let tx=0;tx<nx;tx++){
    const x0=tx*tile, x1=(tx===nx-1)?w:(tx+1)*tile;
    const y0=ty*tile, y1=(ty===ny-1)?h:(ty+1)*tile;
    const buf=[];
    for(let y=y0;y<y1;y+=2)for(let x=x0;x<x1;x+=2){
      const i=y*w+x;
      if(tisFull&&!tisFull[i])continue;      // slide pixels carry no tissue noise
      buf.push(resid[i]);
    }
    if(buf.length<64){map[ty*nx+tx]=-1;continue;}   // resolved below
    buf.sort((a,b)=>a-b);
    const med=buf[buf.length>>1]||0;
    const dev=buf.map(v=>Math.abs(v-med)); dev.sort((a,b)=>a-b);
    const s=Math.max(1e-3,1.4826*(dev[dev.length>>1]||0));
    map[ty*nx+tx]=s; vals.push(s);
  }
  /* A tile that is mostly empty slide has almost no spread, and dividing by it
     turns faint texture into a large z.  Floor every tile at a fraction of the
     typical tissue value, and give the unusable tiles that typical value.     */
  vals.sort((a,b)=>a-b);
  const typical=vals.length?vals[vals.length>>1]:1;
  const floor=typical*0.45;
  for(let i=0;i<map.length;i++) map[i]=map[i]<0?typical:Math.max(map[i],floor);
  return upsample(map,nx,ny,w,h);
}
function channelNormRange(img,tisFull){
  const step=Math.max(1,Math.floor(img.length/250000));
  const vals=[];
  for(let i=0;i<img.length;i+=step){
    const v=img[i];
    if((!tisFull||tisFull[i])&&v!==0&&isFinite(v)) vals.push(v);
  }
  if(vals.length<64){
    vals.length=0;
    for(let i=0;i<img.length;i+=step){const v=img[i];if(v!==0&&isFinite(v))vals.push(v);}
  }
  if(!vals.length)return {lo:0,hi:1,span:1};
  vals.sort((a,b)=>a-b);
  const q=f=>vals[Math.max(0,Math.min(vals.length-1,Math.floor(f*(vals.length-1))))];
  let lo=q(0.001),hi=q(0.998);
  if(!(hi>lo)){lo=vals[0];hi=vals[vals.length-1];}
  if(!(hi>lo))hi=lo+1;
  return {lo:lo,hi:hi,span:hi-lo};
}
/* Return both the classical z map used to FIND somata and a normalized local
   enrichment map used only to decide whether a found soma carries a partner
   marker.  The latter deliberately has no local-sigma denominator. */
function channelScores(img,w,h,dMax,tis,tisFull,keep){
  const bg=localBackground(img,w,h,Math.round(3*dMax),tis);
  const resid=new Float32Array(w*h);
  for(let i=0;i<resid.length;i++) resid[i]=img[i]-bg[i];
  const sig=localSigma(resid,w,h,Math.round(6*dMax),tisFull);
  const z=new Float32Array(w*h);
  for(let i=0;i<z.length;i++) z[i]=resid[i]/Math.max(sig[i],1e-3);
  const range=channelNormRange(img,tisFull);
  const nr=new Float32Array(w*h);
  for(let i=0;i<nr.length;i++) nr[i]=resid[i]/Math.max(range.span,1e-6);
  if(keep){keep.bg=bg;keep.sig=sig;keep.norm=range;}
  return {z:z,nr:nr,norm:range};
}
/* Cytoplasmic stains such as TH leave the nucleus unstained, so a soma can
   look like a bright ring.  Perfectly closed rings are easy: fill the enclosed
   dark component.  Real tissue is messier, though; one side of the cytoplasm
   can be weak enough to leave a 1-3 px break, which makes the nucleus connected
   to the outside and defeats literal hole filling.

   Donut mode therefore does a deliberately conservative reconstruction:
     1. close only tiny breaks in a temporary copy of the threshold mask;
     2. find dark cavities that become enclosed after that tiny closing;
     3. require most of each cavity boundary to be supported by ORIGINAL signal;
     4. add only the accepted cavity plus the small bridge immediately around it.

   The normal detector never uses this path.  The support test is important:
   without it, dark gaps fenced in by dense neuropil can masquerade as nuclei. */
function closeTinyGaps(mask,w,h,r){
  r=Math.max(1,Math.min(3,r|0));
  let a=new Uint8Array(mask);
  for(let pass=0;pass<r;pass++){
    const d=new Uint8Array(w*h);
    for(let y=0;y<h;y++)for(let x=0;x<w;x++){
      let on=0;
      for(let yy=Math.max(0,y-1);yy<=Math.min(h-1,y+1)&&!on;yy++)
        for(let xx=Math.max(0,x-1);xx<=Math.min(w-1,x+1);xx++)
          if(a[yy*w+xx]){on=1;break;}
      d[y*w+x]=on;
    }
    a=d;
  }
  for(let pass=0;pass<r;pass++){
    const e=new Uint8Array(w*h);
    for(let y=0;y<h;y++)for(let x=0;x<w;x++){
      let on=1;
      for(let yy=y-1;yy<=y+1&&on;yy++)for(let xx=x-1;xx<=x+1;xx++){
        if(xx<0||yy<0||xx>=w||yy>=h||!a[yy*w+xx]){on=0;break;}
      }
      e[y*w+x]=on;
    }
    a=e;
  }
  return a;
}
function fillDonutCavities(mask,w,h,maxHole,gapRadius){
  const original=new Uint8Array(mask);
  const closed=closeTinyGaps(mask,w,h,gapRadius);
  const inv=new Uint8Array(w*h);
  for(let i=0;i<inv.length;i++) inv[i]=closed[i]?0:1;
  const cc=labelComponents(inv,w,h);
  const size=new Int32Array(cc.count+1), open=new Uint8Array(cc.count+1);
  const minX=new Int32Array(cc.count+1), minY=new Int32Array(cc.count+1),
        maxX=new Int32Array(cc.count+1), maxY=new Int32Array(cc.count+1);
  minX.fill(w); minY.fill(h); maxX.fill(-1); maxY.fill(-1);
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){
    const L=cc.lab[y*w+x]; if(!L)continue;
    size[L]++;
    if(x<minX[L])minX[L]=x;if(x>maxX[L])maxX[L]=x;
    if(y<minY[L])minY[L]=y;if(y>maxY[L])maxY[L]=y;
  }
  for(let x=0;x<w;x++){
    if(cc.lab[x]) open[cc.lab[x]]=1;
    if(cc.lab[(h-1)*w+x]) open[cc.lab[(h-1)*w+x]]=1;
  }
  for(let y=0;y<h;y++){
    if(cc.lab[y*w]) open[cc.lab[y*w]]=1;
    if(cc.lab[y*w+w-1]) open[cc.lab[y*w+w-1]]=1;
  }

  const accept=new Uint8Array(cc.count+1);
  for(let L=1;L<=cc.count;L++){
    if(open[L]||size[L]<3||size[L]>maxHole)continue;
    /* Count the cavity boundary and ask how much of it touches signal that was
       present before closing.  This tolerates one weak side while still
       demanding that the object is fundamentally a fluorescent shell. */
    let boundary=0,supported=0;
    const x0=Math.max(0,minX[L]-1),x1=Math.min(w-1,maxX[L]+1),
          y0=Math.max(0,minY[L]-1),y1=Math.min(h-1,maxY[L]+1);
    for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){
      const i=y*w+x;if(cc.lab[i]!==L)continue;
      let edge=false,sup=false;
      for(let yy=Math.max(0,y-1);yy<=Math.min(h-1,y+1);yy++)
        for(let xx=Math.max(0,x-1);xx<=Math.min(w-1,x+1);xx++){
          const j=yy*w+xx;
          if(cc.lab[j]!==L){edge=true;if(original[j])sup=true;}
        }
      if(edge){boundary++;if(sup)supported++;}
    }
    if(boundary && supported/boundary>=0.55) accept[L]=1;
  }

  let filled=0;
  for(let i=0;i<mask.length;i++){
    const L=cc.lab[i];
    if(L&&accept[L]&&!mask[i]){mask[i]=1;filled++;}
  }
  /* Keep only the tiny closing bridge near an accepted cavity.  This prevents
     the temporary closing from generally thickening fibres or merging cells. */
  const bridgeR=Math.max(1,Math.min(3,gapRadius|0));
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){
    const i=y*w+x;if(mask[i]||!closed[i]||original[i])continue;
    let near=false;
    for(let yy=Math.max(0,y-bridgeR);yy<=Math.min(h-1,y+bridgeR)&&!near;yy++)
      for(let xx=Math.max(0,x-bridgeR);xx<=Math.min(w-1,x+bridgeR);xx++){
        const L=cc.lab[yy*w+xx];if(L&&accept[L]){near=true;break;}
      }
    if(near){mask[i]=1;filled++;}
  }
  return filled;
}
function labelComponents(mask,w,h){
  const lab=new Int32Array(w*h), st=new Int32Array(w*h); let n=0;
  for(let i=0;i<w*h;i++){
    if(!mask[i]||lab[i])continue;
    n++; let sp=0; st[sp++]=i; lab[i]=n;
    while(sp>0){
      const p=st[--sp], y=(p/w)|0, x=p-y*w;
      for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){
        if(!dx&&!dy)continue;
        const nx=x+dx, ny=y+dy;
        if(nx<0||ny<0||nx>=w||ny>=h)continue;
        const q=ny*w+nx;
        if(mask[q]&&!lab[q]){lab[q]=n;st[sp++]=q;}
      }
    }
  }
  return {lab,count:n};
}
function suppress(idx,w,minDist){
  const cell=Math.max(1,minDist), grid=new Map(), out=[], d2=minDist*minDist;
  for(const i of idx){
    const y=(i/w)|0, x=i-y*w, gx=(x/cell)|0, gy=(y/cell)|0;
    let ok=true;
    for(let a=-1;a<=1&&ok;a++)for(let b=-1;b<=1;b++){
      const bk=grid.get((gy+a)+':'+(gx+b)); if(!bk)continue;
      for(const j of bk){const jy=(j/w)|0,jx=j-jy*w;
        if((jx-x)*(jx-x)+(jy-y)*(jy-y)<d2){ok=false;break;}}
      if(!ok)break;
    }
    if(!ok)continue;
    out.push(i);
    const k=gy+':'+gx; if(!grid.has(k))grid.set(k,[]); grid.get(k).push(i);
  }
  return out;
}
function peakMaxima(field,w,h,mask,minDist,absThresh){
  const cand=[];
  for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){
    const i=y*w+x;
    if(mask&&!mask[i])continue;
    const v=field[i]; if(v<absThresh)continue;
    let pk=true;
    for(let dy=-1;dy<=1&&pk;dy++)for(let dx=-1;dx<=1;dx++){
      if(!dx&&!dy)continue;
      const q=(y+dy)*w+x+dx;
      if(field[q]>v||(field[q]===v&&q<i)){pk=false;break;}
    }
    if(pk)cand.push(i);
  }
  cand.sort((a,b)=>field[b]-field[a]);
  return suppress(cand,w,minDist);
}
function watershed(dt,mask,w,h,seeds){
  const lab=new Int32Array(w*h);
  let maxd=0; for(let i=0;i<dt.length;i++) if(mask[i]&&dt[i]>maxd) maxd=dt[i];
  const L=512, sc=(L-1)/(maxd||1), bk=new Array(L);
  const lvl=p=>Math.min(L-1,Math.max(0,(L-1)-Math.round(dt[p]*sc)));
  seeds.forEach((p,k)=>{lab[p]=k+1;});
  for(const p of seeds){const v=lvl(p);(bk[v]||(bk[v]=[])).push(p);}
  for(let v=0;v<L;v++){
    const q=bk[v]; if(!q)continue;
    for(let qi=0;qi<q.length;qi++){
      const p=q[qi], y=(p/w)|0, x=p-y*w, id=lab[p]; if(!id)continue;
      for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){
        if(!dx&&!dy)continue;
        const nx=x+dx, ny=y+dy;
        if(nx<0||ny<0||nx>=w||ny>=h)continue;
        const n=ny*w+nx;
        if(!mask[n]||lab[n])continue;
        lab[n]=id;
        const vn=lvl(n);
        if(vn<=v) q.push(n); else (bk[vn]||(bk[vn]=[])).push(n);
      }
    }
    bk[v]=null;
  }
  return lab;
}
/* For each soma we keep a histogram of every channel's z-score INSIDE that
   soma, not just the mean.  A mean is fooled by a thin axon of the other
   colour crossing the cell: it lifts the average without the cell actually
   expressing anything.  From a histogram we can ask the question that
   matters — what FRACTION of the soma is positive — and a crossing fibre
   covers only a sliver.                                                    */
const HB=48, HLO=-2, HHI=22;
function hbin(v){
  const i=Math.floor((v-HLO)/(HHI-HLO)*HB);
  return i<0?0:(i>=HB?HB-1:i);
}
function fillFraction(hist,off,total,thr){
  if(!total)return 0;
  let n=0;
  for(let b=hbin(thr);b<HB;b++) n+=hist[off+b];
  return n/total;
}
/* Colocalisation uses a different histogram from soma detection.  Its value is
   (pixel - local background) / the channel's own 0.1..99.8 percentile range.
   That puts dim and bright fluorophores on the same scale WITHOUT using local
   sigma, which is exactly what becomes unstable in dense neuropil. */
const LHB=128, LHLO=-0.25, LHHI=1.00;
function lhbin(v){
  const i=Math.floor((v-LHLO)/(LHHI-LHLO)*LHB);
  return i<0?0:(i>=LHB?LHB-1:i);
}
function localFillFraction(hist,off,total,thr){
  if(!total)return 0;
  let n=0;
  for(let b=lhbin(thr);b<LHB;b++) n+=hist[off+b];
  return n/total;
}
/* A pixel-level "white overlap" score for normalized channels.  min(a,b)
   requires both channels to be locally enriched; multiplying by min/max
   penalizes unequal/tinted pairs.  Thus a broad weak partner or a red/green
   imbalance cannot look colocalized merely because it covers the soma. */
const JHB=128, JHLO=0, JHHI=1.00;
function jointWhiteScore(a,b){
  a=Math.max(0,a); b=Math.max(0,b);
  const hi=Math.max(a,b), lo=Math.min(a,b);
  return hi>1e-9 ? lo*(lo/hi) : 0;
}
function jhbin(v){
  const i=Math.floor((v-JHLO)/(JHHI-JHLO)*JHB);
  return i<0?0:(i>=JHB?JHB-1:i);
}
function jointFillFraction(hist,off,total,thr){
  if(!total)return 0;
  let n=0;
  for(let b=jhbin(thr);b<JHB;b++) n+=hist[off+b];
  return n/total;
}

