  for(let i=0;i<props.length;i++){const q=props[i];if(!q)continue;if(q.major/Math.max(q.minor,1e-6)>p.maxAspect)continue;idx.push(i);
    cand.push({x:q.x,y:q.y,area:q.area,width:q.width,minor:q.minor,major:q.major,aspect:q.major/Math.max(q.minor,1e-6),
      z0:q.z&&q.z.length?q.z[0]:0,peak:q.peak==null?0:q.peak,contrast:(q.raw||0)-(q.bg||0),sigma:q.sig==null?1:q.sig,bg:q.bg==null?1:q.bg});}
  const X=handRfFeatures(cand,p.dMin,p.snr),prob=new Float64Array(props.length).fill(NaN);
  for(let k=0;k<idx.length;k++)prob[idx[k]]=handRfProbability(X[k]);
  const quality=handRfImageQuality(cand),dom=SOMA_HAND_RF.validatedDomain,cal=SOMA_HAND_RF_CALIBRATION;
  return {prob,threshold:cal.threshold,quality,inDomain:quality>=cal.minImageQuality&&quality<=cal.maxImageQuality&&Math.abs(p.dMin-dom.dMinPx)<=1};
